<?php if (empty($galleries)): ?><p class="empty">暂时还没有图集，等待下一次自动采集。</p><?php else: ?><div class="cards"><?php foreach ($galleries as $item): ?><a class="card" href="<?= h(query_url(['route' => 'gallery', 'slug' => $item['slug']])) ?>"><div class="card-cover"><img loading="lazy" src="<?= h(display_image_url((string) $item['cover_path'], (string) ($item['cover_path'] ?? ''))) ?>" alt="<?= h($item['title']) ?>"></div><div class="card-body"><span class="tag"><?= h($item['category_name']) ?></span><h3><?= h($item['title']) ?></h3><p><?= h($item['description']) ?></p></div></a><?php endforeach; ?></div><?php endif; ?>
